func (q *Queries) RetirePreviousSystemRolloutReleases(ctx context.Context, arg RetirePreviousSystemRolloutReleasesParams) error {
	_, err := q.db.Exec(ctx, retirePreviousSystemRolloutReleases, arg.ID, arg.RetiredAt)
	return err
}

