const updateSystemRolloutCounters = `-- name: UpdateSystemRolloutCounters :exec
UPDATE delivery_system_rollouts SET state=$1::text,fencing_generation=fencing_generation+1,
	ready_clusters=$2,failed_clusters=$3,released_clusters=$4,last_error_code=$5,
	started_at=CASE WHEN $1::text IN ('progressing','rolling_back') THEN COALESCE(started_at,now()) ELSE started_at END,
	lease_owner='',lease_expires_at=NULL WHERE id=$6
`

type UpdateSystemRolloutCountersParams struct {
	State            string    `json:"state"`
	ReadyClusters    int32     `json:"ready_clusters"`
	FailedClusters   int32     `json:"failed_clusters"`
	ReleasedClusters int32     `json:"released_clusters"`
	LastErrorCode    string    `json:"last_error_code"`
	ID               uuid.UUID `json:"id"`
}

func (q *Queries) UpdateSystemRolloutCounters(ctx context.Context, arg UpdateSystemRolloutCountersParams) error {
	_, err := q.db.Exec(ctx, updateSystemRolloutCounters,
		arg.State,
		arg.ReadyClusters,
		arg.FailedClusters,
		arg.ReleasedClusters,
		arg.LastErrorCode,
		arg.ID,
	)
	return err
}
